using System;
using UnityEngine;

/// <summary>
/// Carga e inicializa el spritesheet completo de agachado y sigilo para la Vigilante.
/// 15 frames de animaci\u00f3n (3 filas x 5 columnas):
/// - Fila 0 (frames 0-4): Transici\u00f3n De Pie -> Agacharse.
/// - Fila 1 (frames 5-9): Ciclo de caminata agachada en sigilo.
/// - Fila 2 (frames 10-14): Transici\u00f3n Agachada -> De Pie.
/// </summary>
public static class VigilanteCrouchSprites
{
    private static bool inicializado = false;
    private static Texture2D sheetTexture;

    public static Sprite[] CrouchDownFrames { get; private set; }
    public static Sprite[] CrouchWalkFrames { get; private set; }
    public static Sprite[] CrouchUpFrames { get; private set; }
    public static Sprite CrouchIdleSprite => (CrouchWalkFrames != null && CrouchWalkFrames.Length > 0) ? CrouchWalkFrames[0] : null;

    public static bool EstaListo => inicializado && CrouchWalkFrames != null && CrouchWalkFrames.Length > 0;

    public static void Inicializar(float ppuReferencia = 64f)
    {
        if (inicializado && sheetTexture != null) return;

        try
        {
            string b64 = GetBase64Data();
            byte[] bytes = Convert.FromBase64String(b64);
            sheetTexture = new Texture2D(509, 490, TextureFormat.RGBA32, false);
            sheetTexture.filterMode = FilterMode.Bilinear;
            sheetTexture.wrapMode = TextureWrapMode.Clamp;
            sheetTexture.LoadImage(bytes);

            Vector2 pivot = new Vector2(0.5f, 0.5f);

            // Calibración exacta de tamaño:
            // La vigilante original (vigilante_idle) mide 458 píxeles de alto con PPU=300 (1.526 unidades de mundo).
            // Este spritesheet mide 136 píxeles de alto de pie.
            // Para que mantenga exactamente el tamaño normal (y NO se vea pequeña), el PPU se ajusta proporcionalmente:
            float ppu = (ppuReferencia > 0f ? ppuReferencia / 3.36f : 89.2f);

            // Fila 0: De pie a agacharse (5 frames)
            CrouchDownFrames = new Sprite[5]
            {
                Sprite.Create(sheetTexture, new Rect(30f, 340f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(126f, 340f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(221f, 340f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(315f, 340f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(412f, 340f, 64f, 142f), pivot, ppu)
            };

            // Fila 1: Ciclo de caminata agachada en sigilo (5 frames)
            CrouchWalkFrames = new Sprite[5]
            {
                Sprite.Create(sheetTexture, new Rect(30f, 194f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(126f, 194f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(221f, 194f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(315f, 194f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(412f, 194f, 64f, 142f), pivot, ppu)
            };

            // Fila 2: De agachada a levantarse de pie (5 frames)
            CrouchUpFrames = new Sprite[5]
            {
                Sprite.Create(sheetTexture, new Rect(30f, 25f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(126f, 25f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(221f, 25f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(315f, 25f, 64f, 142f), pivot, ppu),
                Sprite.Create(sheetTexture, new Rect(412f, 25f, 64f, 142f), pivot, ppu)
            };

            inicializado = true;
        }
        catch (Exception ex)
        {
            Debug.LogError("[VigilanteCrouchSprites] Error inicializando sprites de agachado: " + ex.Message);
        }
    }

